function id(){return typeof crypto!=="undefined"&&crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random())}
function makeJob(j:Partial<Job>):Job{return {id:id(),company:"",title:"",family:"Other",location:"",salary:"",url:"",jd:"",tags:[],status:"Saved",example:false,addedAt:new Date().toISOString(),resume:"",answers:[],requests:[],revisions:[],submissions:[],timeline:[],...j}}
