if(!session)return <div className="load-state"><span className="brandmark">o</span><h1>Offerdesk</h1><p>{error||"Opening your private workspace…"}</p>{error&&<button className="btn" onClick={()=>{setError("");initialize().catch(e=>setError(e.message))}}>Try again</button>}</div>;
