const [tab,setTab]=useState("Today"),[state,setState]=useState<State|null>(null),[save,setSave]=useState("Loading workspace…"),[loadError,setLoadError]=useState(""),[selected,setSelected]=useState<string|null>(null),[pane,setPane]=useState("Resume"),[query,setQuery]=useState(""),[notice,setNotice]=useState(""),[dialog,setDialog]=useState<string|null>(null),[running,setRunning]=useState(false),[draftRequest,setDraftRequest]=useState(""),[artifact,setArtifact]=useState<Job["submissions"][number]|null>(null),[emailText,setEmailText]=useState(""),[proposal,setProposal]=useState<any>(null),[emailJob,setEmailJob]=useState(""),[form,setForm]=useState<Record<string,string>>({}),[filter,setFilter]=useState("All opportunities");
