useEffect(()=>{fetch("/api/workspace").then(async r=>{if(!r.ok)throw Error(r.status===401?"Sign in to open your private workspace.":"Workspace could not be loaded.");return r.json() as Promise<any>}).then(d=>{serverUpdatedAt.current=d.updatedAt||null;setState(d.state?normalizeState(d.state,profile.masterResume):seed(profile));setSave(d.state?"All changes saved":"New workspace · saving…");loaded.current=true}).catch(e=>{setLoadError(e.message);setSave("Not connected")})},[]);
async function persist(){if(saveBlocked.current||saving.current||!pending.current)return;saving.current=true;const next=pending.current;pending.current=null;setSave("Saving…");try{const r=await fetch("/api/workspace",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({state:next,expectedUpdatedAt:serverUpdatedAt.current})});if(r.status===409){saveBlocked.current=true;setSave("Workspace changed elsewhere · reload to merge");setNotice("Another update changed this workspace. Reload before editing further; export your session first if needed.");throw Error("conflict")}if(!r.ok)throw Error("Save failed");const result:any=await r.json();serverUpdatedAt.current=result.updatedAt;setSave("All changes saved")}catch{if(!saveBlocked.current)setSave("Save failed · changes remain in this session");pending.current=next}finally{saving.current=false;if(pending.current&&pending.current!==next)persist()}}
