async function runAgents(){if(!state)return;setRunning(true);try{const r=await fetch("/api/agents",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({jobs:state.jobs,referrals:state.referrals})});const d:any=await r.json();if(!r.ok)throw Error(d.error||"Could not run workflow");const rankings=new Map((d.jobs||[]).map((j:any)=>[j.id,j]));change(s=>({...s,jobs:s.jobs.map(j=>({...j,...(rankings.get(j.id) as object||{})})),logs:d.logs||[],lastRun:new Date().toISOString()}));setNotice("Rules-based review complete. No new source fetch or AI generation was performed.")}catch(e:any){setNotice(e.message)}finally{setRunning(false)}}
async function fetchJobs(){if(!state)return;if(!profile.sources.length){setNotice("Add a public job board in Profile & sources before fetching opportunities.");return}setRunning(true);try{const r=await fetch("/api/source",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});const d:any=await r.json();if(!r.ok)throw Error(d.error||"Source fetch failed");let count=0;change(s=>{const ids=new Set(s.jobs.map(j=>j.id)),urls=new Set(s.jobs.map(j=>j.url));const additions=(d.jobs||[]).filter((j:any)=>!ids.has(j.id)&&!urls.has(j.url)).map((j:any)=>makeJob({...j,status:"Saved",example:false,addedAt:j.firstSeenAt||d.fetchedAt,salary:"Compensation to verify",resume:profile.masterResume,tags:["Live ATS source"],jd:j.jd||j.description}));count=additions.length;return {...s,jobs:[...additions,...s.jobs],lastSourceFetch:{at:d.fetchedAt,sources:d.sources||[]}}});setNotice(`Public source fetch completed. Existing opportunities and drafts were retained. See source results below.`)}catch(e:any){setNotice(e.message)}finally{setRunning(false)}}
async function fetchNews(){setRunning(true);try{const r=await fetch("/api/news",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});const d:any=await r.json();if(!r.ok)throw Error(d.error||"News fetch failed");change(s=>{const urls=new Set(s.news.map(n=>n.url));return {...s,news:[...(d.items||[]).filter((n:any)=>!urls.has(n.url)).map((n:any)=>({id:id(),title:n.title,body:n.summary,url:n.url,category:n.category,at:n.fetchedAt||d.fetchedAt,publishedAt:n.publishedAt,source:n.source})),...s.news],lastNewsFetch:{at:d.fetchedAt,sources:d.sources||[]}}});setNotice("Source headlines fetched. Read original sources for effective dates and scope.")}catch(e:any){setNotice(e.message)}finally{setRunning(false)}}
async function requestEdit(e:React.FormEvent){e.preventDefault();if(!job||!draftRequest.trim()||chatRunning)return;const message=draftRequest.trim();const originalResume=job.resume,originalAnswers=structuredClone(job.answers),jobId=job.id;updateJob(job.id,{requests:[...job.requests,{text:message,at:new Date().toISOString()}]});setDraftRequest("");if(!capabilities?.modelConfigured){setNotice("Editing request saved. Apply changes manually until a model is connected.");return}setChatRunning(true);try{const r=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({jobId,message,resume:originalResume,questions:originalAnswers.map(a=>a.question)})});const d:any=await r.json();if(!r.ok)throw Error(d.error||"The agent could not prepare a proposal. Your request is saved.");if(!d.proposal)throw Error("The agent returned no proposal. Your request is saved.");setChatProposal({...d,jobId,originalResume,originalAnswers});}catch(e:any){setNotice(e.message)}finally{setChatRunning(false)}}
