async function searchWeb(){if(!capabilities?.webSearchConfigured){setNotice("Optional web search needs your own search-provider key on the server. You can import assistant-researched job URLs without it.");return}if(!confirm("Run up to six search-provider queries? Your provider may charge for these requests. You will review candidates before importing."))return;setRunning(true);try{const r=await fetch("/api/discovery",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});const d:any=await r.json();if(!r.ok)throw Error(d.error||"Web discovery failed.");setDiscovery(d);setDiscoverySelected((d.jobs||[]).map((j:any)=>j.url));setDialog("discovery")}catch(e:any){setNotice(e.message)}finally{setRunning(false)}}
